import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { getCurrentTeamId } from 'lib/utils/getAppContext'

import * as api from '../../generated/api'
import type { AiScanReportApi, AiScanStatusApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface ticketPatternAiScanLogicValues {
    reports: AiScanReportApi[]
    reportsFailed: boolean
    reportsLoading: boolean
    status: AiScanStatusApi | null
    statusLoading: boolean
    toggling: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface ticketPatternAiScanLogicActions {
    disableScan: () => any
    enableScan: () => any
    loadReports: () => any
    loadReportsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadReportsSuccess: (
        reports: AiScanReportApi[],
        payload?: any
    ) => {
        reports: AiScanReportApi[]
        payload?: any
    }
    loadStatus: () => any
    loadStatusFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadStatusSuccess: (
        status: AiScanStatusApi | null,
        payload?: any
    ) => {
        status: AiScanStatusApi | null
        payload?: any
    }
    setToggling: (toggling: boolean) => {
        toggling: boolean
    }
}

export type ticketPatternAiScanLogicType = MakeLogicType<
    ticketPatternAiScanLogicValues,
    ticketPatternAiScanLogicActions
>

export const ticketPatternAiScanLogic = kea<ticketPatternAiScanLogicType>([
    path(['products', 'conversations', 'frontend', 'components', 'TicketPatterns', 'ticketPatternAiScanLogic']),
    actions({
        enableScan: true,
        disableScan: true,
        setToggling: (toggling: boolean) => ({ toggling }),
    }),
    loaders(() => ({
        status: [
            null as AiScanStatusApi | null,
            {
                loadStatus: async () => api.conversationsPatternAiScanStatusRetrieve(String(getCurrentTeamId())),
            },
        ],
        reports: [
            [] as AiScanReportApi[],
            {
                loadReports: async () => api.conversationsPatternAiScanReportsList(String(getCurrentTeamId())),
            },
        ],
    })),
    reducers({
        // A failed load leaves `reports` empty, which is the same shape as a scan that has filed
        // nothing. The section must not read one as the other and tell the reader the scan is quiet.
        reportsFailed: [
            false,
            {
                loadReports: () => false,
                loadReportsSuccess: () => false,
                loadReportsFailure: () => true,
            },
        ],
        toggling: [
            false,
            {
                enableScan: () => true,
                disableScan: () => true,
                setToggling: (_, { toggling }) => toggling,
            },
        ],
    }),
    listeners(({ actions }) => ({
        enableScan: async () => {
            try {
                const status = await api.conversationsPatternAiScanCreate(String(getCurrentTeamId()))
                actions.loadStatusSuccess(status)
            } catch (error: any) {
                lemonToast.error(error?.detail ?? "Couldn't turn on the AI scan. Try again.")
            } finally {
                actions.setToggling(false)
            }
        },
        disableScan: async () => {
            try {
                await api.conversationsPatternAiScanDisableCreate(String(getCurrentTeamId()))
                actions.loadStatus()
            } catch (error: any) {
                lemonToast.error(error?.detail ?? "Couldn't turn off the AI scan. Try again.")
            } finally {
                actions.setToggling(false)
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadStatus()
    }),
])
